package io.github.alighaziam.eom.outbox.infrastructure;
import io.github.alighaziam.eom.outbox.IntegrationEvent; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="outbox_events",schema="messaging") public class OutboxEntity {
 @Id @Column(name="event_id") private UUID eventId; @Column(name="event_type",nullable=false,length=160) private String eventType; @Column(name="schema_version",nullable=false) private int schemaVersion; @Column(name="occurred_at",nullable=false) private Instant occurredAt; @Column(name="aggregate_type",nullable=false,length=120) private String aggregateType; @Column(name="aggregate_id",nullable=false,length=120) private String aggregateId; @Column(name="aggregate_version",nullable=false) private long aggregateVersion; @Column(name="correlation_id",nullable=false,length=120) private String correlationId; @Column(name="causation_id",length=120) private String causationId; @Column(nullable=false,columnDefinition="text") private String payload; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="published_at") private Instant publishedAt; @Column(nullable=false) private int attempts; @Column(name="last_error",length=1000) private String lastError;
 protected OutboxEntity(){} public OutboxEntity(UUID id,String type,int version,Instant occurred,String at,String aid,long av,String cid,String cause,String payload,Instant created){eventId=id;eventType=type;schemaVersion=version;occurredAt=occurred;aggregateType=at;aggregateId=aid;aggregateVersion=av;correlationId=cid;causationId=cause;this.payload=payload;createdAt=created;}
 public IntegrationEvent toEvent(){return new IntegrationEvent(eventId,eventType,schemaVersion,occurredAt,aggregateType,aggregateId,aggregateVersion,correlationId,causationId,payload);}
 public void published(Instant at){publishedAt=at;lastError=null;} public void failed(String error){attempts++;lastError=error==null?"Unknown relay failure":error.substring(0,Math.min(1000,error.length()));}
}